graphql.query:
query LocalizationDiscovery {
  localization {
    availableCountries {
      isoCode
      name
      availableLanguages {
        isoCode
        name
      }
      currency {
        isoCode
        symbol
      }
    }
  }
}

query CatalogCollection(
  $handle: String!
  $productCount: Int!
  $country: CountryCode
  $language: LanguageCode
) @inContext(country: $country, language: $language) {
  collection(handle: $handle) {
    products(first: $productCount, sortKey: CREATED, reverse: false) {
      nodes {
        ...CollectionProductCard
      }
    }
  }
}
fragment CollectionProductCard on Product {
  id
  handle
  title
  productType
  availableForSale
  descriptionHtml
  featuredImage { url altText width height }
  priceRange { minVariantPrice { amount currencyCode } }
  collections(first: 5) {
    nodes {
      handle
    }
  }
  metafields(identifiers: [
    { namespace: "custom", key: "subtitle" }
    { namespace: "custom", key: "notes" }
    { namespace: "custom", key: "short_description" }
  ]) {
    key
    type
    value
  }
}

query CatalogProductDetail(
  $handle: String!
  $country: CountryCode
  $language: LanguageCode
) @inContext(country: $country, language: $language) {
  product(handle: $handle) {
    id
    handle
    title
    productType
    availableForSale
    descriptionHtml
    featuredImage { url altText width height }
    priceRange { minVariantPrice { amount currencyCode } }
    images(first: 10) { nodes { url altText width height } }
    collections(first: 5) {
      nodes {
        handle
      }
    }
    variants(first: 20) {
      nodes {
        id
        title
        sku
        availableForSale
        quantityAvailable
        price { amount currencyCode }
        selectedOptions { name value }
        metafield(namespace: "custom", key: "title") {
          value
        }
      }
    }
    metafields(identifiers: [
      { namespace: "custom", key: "subtitle" }
      { namespace: "custom", key: "notes" }
      { namespace: "custom", key: "set_includes" }
      { namespace: "custom", key: "short_description" }
      { namespace: "custom", key: "product_info" }
      { namespace: "custom", key: "serving" }
      { namespace: "custom", key: "delivery" }
      { namespace: "custom", key: "gifting" }
      { namespace: "custom", key: "related_products" }
    ]) {
      key
      type
      value
      references(first: 10) {
        nodes {
          ... on Product { ...CatalogProductCard }
        }
      }
    }
  }
}
fragment CatalogProductCard on Product {
  id
  handle
  title
  productType
  availableForSale
  descriptionHtml
  featuredImage { url altText width height }
  priceRange { minVariantPrice { amount currencyCode } }
  collections(first: 5) {
    nodes {
      handle
    }
  }
  metafields(identifiers: [
    { namespace: "custom", key: "subtitle" }
    { namespace: "custom", key: "notes" }
    { namespace: "custom", key: "short_description" }
  ]) {
    key
    type
    value
  }
}

query CatalogHandles(
  $country: CountryCode
  $language: LanguageCode
) @inContext(country: $country, language: $language) {
  collection(handle: "our-caviar") {
    products(first: 50, sortKey: CREATED, reverse: false) {
      nodes { handle }
    }
  }
}

query GetShopInfo {
  shop {
    id
    name
    brand {
      logo { image { url } }
      slogan
      shortDescription
    }
    description
    primaryDomain { host url }
    paymentSettings {
      countryCode
      currencyCode
    }
  }
}

mutation MaisonCartCreate($input: CartInput!, $first: Int!, $after: String, $language: LanguageCode)
@inContext(language: $language) {
  cartCreate(input: $input) {
    cart {
      id totalQuantity checkoutUrl buyerIdentity { countryCode }
      cost { subtotalAmount { amount currencyCode } }
      lines(first: $first, after: $after) {
        pageInfo { hasNextPage endCursor }
        nodes {
          id quantity attributes { key value }
          cost { amountPerQuantity { amount currencyCode } subtotalAmount { amount currencyCode } }
          merchandise { ... on ProductVariant {
            id title availableForSale quantityAvailable selectedOptions { name value }
            metafield(namespace: "custom", key: "title") { value }
            image { url altText width height }
            product { id handle title productType }
          } }
        }
      }
    }
    userErrors { code field message }
    warnings { code target message }
  }
}

query MaisonCartQuery(
  $id: ID!
  $first: Int!
  $after: String
  $language: LanguageCode
) @inContext(language: $language) {
  cart(id: $id) {
    id
    totalQuantity
    checkoutUrl
    buyerIdentity { countryCode }
    cost { subtotalAmount { amount currencyCode } }
    lines(first: $first, after: $after) {
      pageInfo { hasNextPage endCursor }
      nodes {
        id
        quantity
        attributes { key value }
        cost {
          amountPerQuantity { amount currencyCode }
          subtotalAmount { amount currencyCode }
        }
        merchandise {
          ... on ProductVariant {
            id
            title
            availableForSale
            quantityAvailable
            selectedOptions { name value }
            metafield(namespace: "custom", key: "title") { value }
            image { url altText width height }
            product { id handle title productType }
          }
        }
      }
    }
  }
}

